from functools import wraps
import time

def timed(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = fn(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f'{fn.__name__}: {elapsed:.4f}s')
        return result
    return wrapper

@timed
def total(n):
    return sum(range(n))

print(total(1000))

